1	import { FIT_SCORE_WEIGHTS } from "@/lib/constants";
2	
3	// Deterministic audience-fit score (0..100): how well a creator's audience
4	// matches a campaign's ICP. Naano's headline "which creators your buyers
5	// trust" metric — audience composition matters, follower count does not.
6	
7	export type IcpTarget = {
8	  functions: string[];
9	  seniorities: string[];
10	  vertical?: string | null;
11	};
12	
13	export type CreatorAudience = {
14	  audienceByFunction: Record<string, number>;
15	  audienceBySeniority: Record<string, number>;
16	  verticals: string[];
17	};
18	
19	/** Coerce a Prisma Json value into a { label: fraction } map defensively. */
20	export function asAudienceMap(value: unknown): Record<string, number> {
21	  if (!value || typeof value !== "object") return {};
22	  const out: Record<string, number> = {};
23	  for (const [key, raw] of Object.entries(value as Record<string, unknown>)) {
24	    const num = typeof raw === "number" ? raw : Number(raw);
25	    if (Number.isFinite(num)) out[key] = num;
26	  }
27	  return out;
28	}
29	
30	function coverage(audience: Record<string, number>, targets: string[]): number {
31	  if (targets.length === 0) return 0.5; // no preference expressed → neutral
32	  const total = targets.reduce((sum, label) => sum + (audience[label] ?? 0), 0);
33	  return Math.max(0, Math.min(1, total));
34	}
35	
36	function verticalMatch(creatorVerticals: string[], vertical?: string | null): number {
37	  if (!vertical) return 0.5;
38	  return creatorVerticals.includes(vertical) ? 1 : 0.25;
39	}
40	
41	export function computeFitScore(target: IcpTarget, creator: CreatorAudience): number {
42	  const functionScore = coverage(creator.audienceByFunction, target.functions);
43	  const seniorityScore = coverage(creator.audienceBySeniority, target.seniorities);
44	  const vertical = verticalMatch(creator.verticals, target.vertical);
45	
46	  const weighted =
47	    FIT_SCORE_WEIGHTS.functionMatch * functionScore +
48	    FIT_SCORE_WEIGHTS.seniorityMatch * seniorityScore +
49	    FIT_SCORE_WEIGHTS.verticalMatch * vertical;
50	
51	  const raw = weighted * 100;
52	  const hasSignal = functionScore > 0 || seniorityScore > 0;
53	  const floored = hasSignal ? Math.max(raw, FIT_SCORE_WEIGHTS.floor) : raw;
54	  return Math.round(Math.max(0, Math.min(100, floored)));
55	}
