        <Textarea
          id="draftContent"
          name="draftContent"
          value={content}
          maxLength={DRAFT_MAX_CHARS}
          onChange={(event) => setContent(event.target.value)}
          placeholder="Hook the reader in the first line, weave in the brief's key messages, and end with the call to action…"
          className="min-h-48"
